import Foundation

/// Keys generated by setup on this device that have not published a given
/// list kind yet. Such a key cannot have that list anywhere, so "no list
/// found" is the truth, not a relay that hasn't answered. Kept per kind and
/// cleared by that kind's first publish only: joining by scan publishes the
/// follow list (3) at setup end, and that must not take the pass away from
/// the first interest list (10015) save (NV_NEW_USER_SCAN_HASHTAG_2026_11_26).
enum FreshAccountKeys {
    private static let key = "freshAccountKeys"
    /// The list kinds setup marks for a key it just made.
    static let newAccountKinds = [3, 10015]

    /// Kind 3 is stored as the bare key, as before kinds were kept.
    private static func entry(_ hex: String, kind: Int) -> String {
        kind == 3 ? hex : "\(hex):\(kind)"
    }

    static func mark(_ hex: String, kinds: [Int], defaults: UserDefaults = .standard) {
        guard !hex.isEmpty else { return }
        var keys = Set(defaults.stringArray(forKey: key) ?? [])
        for kind in kinds { keys.insert(entry(hex, kind: kind)) }
        defaults.set(Array(keys), forKey: key)
    }

    static func isFresh(_ hex: String, kind: Int, defaults: UserDefaults = .standard) -> Bool {
        !hex.isEmpty && (defaults.stringArray(forKey: key) ?? []).contains(entry(hex, kind: kind))
    }

    static func clear(_ hex: String, kind: Int, defaults: UserDefaults = .standard) {
        let name = entry(hex, kind: kind)
        guard var keys = defaults.stringArray(forKey: key), let index = keys.firstIndex(of: name) else { return }
        keys.remove(at: index)
        defaults.set(keys, forKey: key)
    }
}
